/** "gold", "the cyan one", "forest & coral" → a theme, or null (the same matching as the phone's Themes.find). */
export function findTheme(words) {
  const w = String(words || '').trim().toLowerCase();
  if (!w) return null;
  const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return THEMES.find((t) => t.id === w || t.name.toLowerCase() === w)
    || THEMES.find((t) => t.aliases.some((a) => w === a || new RegExp('\\b' + esc(a) + '\\b').test(w))) || null;
}
